import assert from 'node:assert/strict';
import { test } from 'node:test';
import { readFileSync } from 'node:fs';

// The offline mutation run (sidecars/report-lookup/test_mutations.py, docs/clinical-validation/report-lookup-offline-v1.md) is a manual
// step: ten jest runs. Its anchors are exact source text. After the Prettier commit 43278990 two of them matched nothing, so the run could
// only stop with "mutation anchor drift", and nothing noticed (found 2026-11-19). This guard reads the same mutants.json on every pull
// request: an anchor must appear exactly once in its file. Oracle names are not checked here (some are generated by a template, such as
// "canonical / canonical"); the manual run already fails a mutant whose oracle matches no test.
const root = new URL('../../', import.meta.url);
const spec = JSON.parse(readFileSync(new URL('sidecars/report-lookup/mutants.json', root), 'utf8'));
const source = (file) => readFileSync(new URL(`${spec.module}${file}`, root), 'utf8');
const occurrences = (text, anchor) => text.split(anchor).length - 1;
/** The anchors of one mutant that do not appear exactly once in `text`. */
const drifted = (mutant, text) => mutant.replacements.filter(([anchor]) => occurrences(text, anchor) !== 1).map(([anchor]) => anchor);

test('every report-lookup mutation anchor appears exactly once in its source file', () => {
  assert.ok(spec.mutants.length > 0, 'mutants.json lists mutants');
  assert.equal(new Set(spec.mutants.map((m) => m.id)).size, spec.mutants.length, 'mutant ids are unique');
  for (const mutant of spec.mutants) {
    assert.ok(mutant.replacements.length > 0, `${mutant.id} changes something`);
    assert.deepEqual(drifted(mutant, source(mutant.file)), [], `${mutant.id}: anchor drift in ${mutant.file}`);
    for (const [anchor, replacement] of mutant.replacements) assert.notEqual(anchor, replacement, `${mutant.id}: a replacement that changes nothing`);
    assert.ok(mutant.oracle.length > 0, `${mutant.id} names an oracle test`);
  }
});

test('control: the check goes red on a missing anchor and on one that appears twice', () => {
  // A multi-line anchor, so "reformatted" really changes it: joined onto one line, as before Prettier split it.
  const mutant = spec.mutants.find((m) => m.replacements.some(([anchor]) => anchor.includes('\n')));
  assert.ok(mutant, 'a mutant with a multi-line anchor');
  const [anchor] = mutant.replacements.find(([a]) => a.includes('\n'));
  const text = source(mutant.file);
  assert.deepEqual(drifted(mutant, text), []);
  assert.deepEqual(drifted(mutant, text.replace(anchor, anchor.replace(/\s+/g, ' '))), [anchor], 'reformatted (the 43278990 case)');
  assert.deepEqual(drifted(mutant, `${text}\n${anchor}`), [anchor], 'duplicated');
});
